    function avatarOf(id) { var u = user(id); return img(u.avatar, u.avatarUrl); }
    function size(n) { if (!n && n !== 0) return ""; var u = ["o", "Ko", "Mo", "Go"]; if (D.lang !== "fr") u = ["B", "KB", "MB", "GB"]; var i = 0; while (n >= 1024 && i < 3) { n /= 1024; i++; } return (i ? n.toFixed(1) : n) + " " + u[i]; }

    // \u2500\u2500 Markdown (texte \xE9chapp\xE9 d'abord, puis seulement nos balises) \u2500\u2500
